#pragma once
#include "sfm_vtx_geometry.h"
#include "model_skinning_geometry.h"
#include "model_material_metadata.h"
#include "model_eyeball_metadata_candidate.h"
#include <map>
#include <tuple>
struct SfmModelMeshGeometryCandidate {uint32_t body=0,model=0,mesh=0;int32_t material=0,materialType=0,materialParameter=0;std::vector<std::array<uint32_t,3>>triangles;};
struct SfmModelGeometryCandidate {uint32_t checksum=0;VvdGeometryCandidate geometry;std::vector<GeometryBoneCandidate>bones;std::vector<SfmModelMeshGeometryCandidate>meshes;ModelMaterialMetadataCandidate materials;std::vector<uint32_t>bodyModelCounts,bodyBases;std::vector<ModelEyeballCandidate>eyeballs;bool staticGeometry=false;};
// Explicit MDL49/SFM VTX7 LOD0 branch candidate. VVD fixups are applied by
// readVvdGeometryCandidate before MDL model and mesh vertex spans are resolved.
inline SfmModelGeometryCandidate readSfmModelGeometryCandidate(const std::vector<uint8_t>&mdl,const std::vector<uint8_t>&vvd,const std::vector<uint8_t>&vtx){
 auto range=[&](uint64_t o,uint64_t n){if(o>mdl.size()||n>mdl.size()-o)throw std::runtime_error("MDL geometry span");};
 auto word=[&](size_t o){range(o,4);uint32_t v;std::memcpy(&v,mdl.data()+o,4);return v;};
 auto nonnegative=[&](size_t o){auto v=word(o);if(v>INT32_MAX)throw std::runtime_error("negative MDL geometry field");return v;};
 auto relative=[&](size_t base,size_t field){int32_t r;auto raw=word(base+field);std::memcpy(&r,&raw,4);int64_t result=int64_t(base)+r;if(result<0)throw std::runtime_error("MDL relative offset");return size_t(result);};
 auto table=[&](size_t base,size_t co,size_t oo,size_t stride){auto count=nonnegative(base+co);auto start=relative(base,oo);range(start,uint64_t(count)*stride);return std::pair<size_t,uint32_t>{start,count};};
 range(0,240);if(word(0)!=0x54534449||word(4)!=49||word(76)!=mdl.size())throw std::runtime_error("MDL49 geometry header");if(vvd.size()<64)throw std::runtime_error("VVD header");
 SfmModelGeometryCandidate result;result.checksum=word(8);result.geometry=readVvdGeometryCandidate(vvd,result.checksum,0);result.bones=readGeometrySkeletonCandidate(mdl);result.materials=readModelMaterialMetadataCandidate(mdl);
 struct MeshSpan {uint32_t first,count;int32_t material,materialType,materialParameter;};using Key=std::tuple<uint32_t,uint32_t,uint32_t>;std::map<Key,MeshSpan>metadata;auto bodies=table(0,232,236,16);
 for(uint32_t bi=0;bi<bodies.second;++bi){size_t body=bodies.first+size_t(bi)*16;auto models=table(body,4,12,148);auto bodyBase=nonnegative(body+8);if(!bodyBase||!models.second)throw std::runtime_error("invalid MDL body group metadata");result.bodyBases.push_back(bodyBase);result.bodyModelCounts.push_back(models.second);for(uint32_t mi=0;mi<models.second;++mi){size_t model=models.first+size_t(mi)*148;auto eyes=table(model,100,104,172);for(uint32_t eye=0;eye<eyes.second;++eye)result.eyeballs.push_back(readModelEyeballCandidate(mdl,eyes.first+size_t(eye)*172,bi,mi,result.bones.size()));auto count=nonnegative(model+80),vertexBytes=nonnegative(model+84);if(vertexBytes%48)throw std::runtime_error("MDL vertex alignment");auto first=vertexBytes/48;if(first>result.geometry.vertices.size()||count>result.geometry.vertices.size()-first)throw std::runtime_error("MDL model VVD span");auto meshes=table(model,72,76,116);for(uint32_t mei=0;mei<meshes.second;++mei){size_t mesh=meshes.first+size_t(mei)*116;auto meshCount=nonnegative(mesh+8),meshFirst=nonnegative(mesh+12);if(meshFirst>count||meshCount>count-meshFirst)throw std::runtime_error("MDL mesh model span");if(relative(mesh,4)!=model)throw std::runtime_error("MDL mesh parent");int32_t material;auto raw=word(mesh);std::memcpy(&material,&raw,4);int32_t materialType,materialParameter;auto typeBits=word(mesh+24),parameterBits=word(mesh+28);std::memcpy(&materialType,&typeBits,4);std::memcpy(&materialParameter,&parameterBits,4);metadata.emplace(Key{bi,mi,mei},MeshSpan{first+meshFirst,meshCount,material,materialType,materialParameter});}}}
 auto topology=readSfmVtxGeometryCandidate(vtx,result.checksum);for(auto&source:topology){if(source.lod)continue;auto it=metadata.find(Key{source.body,source.model,source.mesh});if(it==metadata.end())throw std::runtime_error("VTX mesh absent from MDL");auto span=it->second;SfmModelMeshGeometryCandidate mesh;mesh.body=source.body;mesh.model=source.model;mesh.mesh=source.mesh;mesh.material=span.material;mesh.materialType=span.materialType;mesh.materialParameter=span.materialParameter;result.materials.resolve(0,mesh.material);mesh.triangles=std::move(source.triangles);for(auto&t:mesh.triangles)for(auto&v:t){if(v>=span.count)throw std::runtime_error("VTX original vertex exceeds MDL mesh");v+=span.first;}result.meshes.push_back(std::move(mesh));metadata.erase(it);}if(!metadata.empty())throw std::runtime_error("MDL mesh absent from VTX");return result;
}
